import { HttpClient, HttpHeaders, HttpParams } from '@angular/common/http';
import { Injectable } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { environment } from '../../../../environments/environment';
import { SecureStorageService } from '../../../core/services/storage/secure-storage.service';
import { adminCaseData, updateAcrchivResponce } from '../../interfaces/admindashboard.interface';

@Injectable({
  providedIn: 'root'
})
export class AdmindashboardService {

  constructor(private http: HttpClient, public sStore: SecureStorageService) { }


  async getDashboardlist(nPageNumber: number,cSearch:string): Promise<any> {
    let params = new HttpParams().set('pageNumber', nPageNumber);
    params = params.append('cSearch', cSearch || '');
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl}${environment.coreservice}/admin-dashboard/caselist`,
          { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }

    return await this.dashBoardArrenge(res);
  }


  async getArchivelist(nPageNumber: number): Promise<any> {
    let params = new HttpParams().set('pageNumber', nPageNumber);
    params = params.append('cSearch', '');
    let res: any = [];
    try {
      res = await firstValueFrom(
        this.http.get<any>(
          `${environment.cloudUrl}${environment.coreservice}/admin-dashboard/archiveCase`,
          { params: params }
        )
      );
    } catch (error) {
      console.error(error)
      res = [];
    }

    return await this.dashBoardArrenge(res);
  }


  async dashBoardArrenge(res): Promise<adminCaseData[]> {
    if (!res || res.length != 3) {
      return [];
    }
    let caseList = res[0];
    for (let x of res[1]) {
      x.users = [];
      x.users = res[2].filter(a => a.teams.includes(x.nTeamid));
    }
    for (let x of caseList) {
      x.teams = [];
      x.teams = res[1].filter(a => a.nCaseid == x.nCaseid);
    }

    return caseList;
  }




  async update_archivecase(mdl): Promise<boolean> {
    try {
      const res: any = await firstValueFrom(
        this.http.post<updateAcrchivResponce>(`${environment.cloudUrl}${environment.coreservice}/admin-dashboard/updatearchiveCase`, mdl)
      );
      if (res && res.msg == 1) {
        return true;
      } else {
        return false;
      }
    } catch (err) {
      return false;
    }
  }


}
